def process(wollaston_adjusted) -> pd.DataFrame:
    df = wollaston_adjusted.dropna(subset=['Rain_3day', 'Entero_Adjusted'])

    correlation = df['Rain_3day'].corr(df['Entero_Adjusted'])

    return pd.DataFrame({'Pearson_Correlation': [round(correlation, 3)]})
